use vstd::prelude::*;
use vstd::vec::*;

verus! {

fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> Vec<f64>
    requires
        // Matrix has at least one row
        choices.len() > 0,
        // Every row is non-empty
        forall|i: int| 0 <= i && i < choices.len() ==> choices[i].len() > 0,
        // All rows have the same length as indices
        forall|i: int| 0 <= i && i < choices.len() ==> choices[i].len() == indices.len(),
        // All indices are valid row selectors
        forall|i: int| 0 <= i && i < indices.len() ==> 
            (indices[i] as int) < choices.len(),
    ensures
        // Result length equals indices length
        result.len() == indices.len(),
        // Each element in result is correctly chosen
        forall|i: int| 0 <= i && i < indices.len() ==> 
            result[i] == choices[indices[i] as int][i],
{
    let mut result = Vec::new();
    let mut i: usize = 0;
    
    while i < indices.len() 
        invariant
            0 <= i && i <= indices.len(),
            result.len() == i,
            forall|j: int| 0 <= j && j < i ==> 
                result[j] == choices[indices[j] as int][j],
    {
        let row_index = indices[i] as usize;
        let element = choices[row_index][i];
        result.push(element);
        i += 1;
    }
    
    result
}

} // verus!